mapper:
{#each models}

{#each columns}    
{/each}  
{/each}
{#each mapper.methods}
{#if select}

{#each properties}{#if column}    {/if}{#if lookup}    {/if}{#if count}    {/if}
{#if parts}{#each parts}    
{/each}{/if}{/each}
{#each properties}{#if collection}    {/if}
{/each}  
{/if}
{/each}
{#each mapper.methods}
{#if select}

    SELECT 
{#each baseBindings}      {table}.{column},
{/each}
{#each properties}{#if column}      {table}.{column} AS {name},{/if}
{#if lookup}      (SELECT n.{lookup.column} FROM {lookup.table} n WHERE n.{lookup.key} = {table}.{lookup.parentColumn}) AS {name},{/if}
{#if count}{#if count}
{#if count.incoming}(SELECT COUNT(DISTINCT c.{count.incoming.key}) FROM {count.incoming.table} c
{#if count.incoming.join}JOIN {count.incoming.join.table} r ON {#each count.incoming.join.keys}r.{column} = c.{parentColumn}{#if more} AND {/if}{/each}{/if}
WHERE {count.incoming.alias}.{count.incoming.reference} = {table}.{count.incoming.parentColumn}{#if count.axis} AND c.{count.axis.column} = {count.axis.value:sql-string-xml}{/if}){/if}
{#if count.child}(SELECT COUNT(*) FROM {count.child.table} c WHERE {#each count.child.keys}c.{column} = {table}.{parentColumn}{#if more} AND {/if}{/each}
{#if count.conditions}{#each count.conditions}
{#if optional}{/if}
{#if compare}AND c.{column} {symbol:xml} {#if param}#{{input.{param}}}{/if}{#if literal}{#if quoted}{constant:sql-string-xml}{/if}{#if plain}{constant:xml}{/if}{/if}{/if}
{#if notNull}AND c.{column} IS NOT NULL{/if}
{#if inValues}AND c.{column} IN ({#each values}{#if quoted}{value:sql-string-xml}{/if}{#if plain}{value:xml}{/if}{#if more}, {/if}{/each}){/if}
{#if startsWith}AND LEFT(c.{column}, CHAR_LENGTH({prefix:sql-string-xml})) = {prefix:sql-string-xml}{/if}
{#if collection}AND EXISTS (SELECT 1 FROM {link.table} l WHERE {#each link.keys}l.{column} = {table}.{parentColumn} AND {/each}l.{link.element.column} IN #{{item}})1 = 0{/if}
{#if optional}{/if}
{/each}{/if}){/if}
{/if} AS {name},{/if}
{#if parts}{#each parts}{#if count}
{#if count.incoming}(SELECT COUNT(DISTINCT c.{count.incoming.key}) FROM {count.incoming.table} c
{#if count.incoming.join}JOIN {count.incoming.join.table} r ON {#each count.incoming.join.keys}r.{column} = c.{parentColumn}{#if more} AND {/if}{/each}{/if}
WHERE {count.incoming.alias}.{count.incoming.reference} = {table}.{count.incoming.parentColumn}{#if count.axis} AND c.{count.axis.column} = {count.axis.value:sql-string-xml}{/if}){/if}
{#if count.child}(SELECT COUNT(*) FROM {count.child.table} c WHERE {#each count.child.keys}c.{column} = {table}.{parentColumn}{#if more} AND {/if}{/each}
{#if count.conditions}{#each count.conditions}
{#if optional}{/if}
{#if compare}AND c.{column} {symbol:xml} {#if param}#{{input.{param}}}{/if}{#if literal}{#if quoted}{constant:sql-string-xml}{/if}{#if plain}{constant:xml}{/if}{/if}{/if}
{#if notNull}AND c.{column} IS NOT NULL{/if}
{#if inValues}AND c.{column} IN ({#each values}{#if quoted}{value:sql-string-xml}{/if}{#if plain}{value:xml}{/if}{#if more}, {/if}{/each}){/if}
{#if startsWith}AND LEFT(c.{column}, CHAR_LENGTH({prefix:sql-string-xml})) = {prefix:sql-string-xml}{/if}
{#if collection}AND EXISTS (SELECT 1 FROM {link.table} l WHERE {#each link.keys}l.{column} = {table}.{parentColumn} AND {/each}l.{link.element.column} IN #{{item}})1 = 0{/if}
{#if optional}{/if}
{/each}{/if}){/if}
{/if} AS {name},
{/each}{/if}{/each}    
    FROM {table}
    {#each conditions}
{#if optional}{/if}
{#if compare}AND {table}.{column} {symbol:xml} {#if param}#{{input.{param}}}{/if}{#if literal}{#if quoted}{constant:sql-string-xml}{/if}{#if plain}{constant:xml}{/if}{/if}{/if}
{#if notNull}AND {table}.{column} IS NOT NULL{/if}
{#if inValues}AND {table}.{column} IN ({#each values}{#if quoted}{value:sql-string-xml}{/if}{#if plain}{value:xml}{/if}{#if more}, {/if}{/each}){/if}
{#if startsWith}AND LEFT({table}.{column}, CHAR_LENGTH({prefix:sql-string-xml})) = {prefix:sql-string-xml}{/if}
{#if collection}AND EXISTS (SELECT 1 FROM {link.table} l WHERE {#each link.keys}l.{column} = {table}.{parentColumn} AND {/each}l.{link.element.column} IN #{{item}})1 = 0{/if}
{#if optional}{/if}
{/each}
{#if order}    ORDER BY {#each order}{table}.{column} {direction}{#if nulls} NULLS {nulls}{/if}{#if more}, {/if}{/each}{/if}

{#each properties}{#if collection}

    SELECT {#if collection.target}n.{collection.target.column}{/if}{#if collection.directScalar}c.{collection.column}{/if}{#if collection.rowMap}c.*{/if}
    FROM {collection.query.table} c
{#if collection.target}    JOIN {collection.target.table} n ON {#each collection.target.keys}c.{column} = n.{parentColumn}{#if more} AND {/if}{/each}{/if}
    WHERE {#each collection.query.keys}c.{column} = #{{k{index}}}{#if more} AND {/if}{/each}
{#if collection.order}    ORDER BY {#each collection.order}c.{column}{#if more}, {/if}{/each}{/if}

{/if}{/each}{/if}
{#if count}

    SELECT COUNT(*) FROM {table}
{#if joins}{#each joins}    JOIN {table} ON {table}.{column} = {outerTable}.{other}
{/each}{/if}    {#each conditions}
{#if optional}{/if}
{#if compare}AND {table}.{column} {symbol:xml} {#if param}#{{input.{param}}}{/if}{#if literal}{#if quoted}{constant:sql-string-xml}{/if}{#if plain}{constant:xml}{/if}{/if}{/if}
{#if notNull}AND {table}.{column} IS NOT NULL{/if}
{#if inValues}AND {table}.{column} IN ({#each values}{#if quoted}{value:sql-string-xml}{/if}{#if plain}{value:xml}{/if}{#if more}, {/if}{/each}){/if}
{#if startsWith}AND LEFT({table}.{column}, CHAR_LENGTH({prefix:sql-string-xml})) = {prefix:sql-string-xml}{/if}
{#if collection}AND EXISTS (SELECT 1 FROM {link.table} l WHERE {#each link.keys}l.{column} = {table}.{parentColumn} AND {/each}l.{link.element.column} IN #{{item}})1 = 0{/if}
{#if optional}{/if}
{/each}

{/if}
{#if max}

    SELECT {#if numericMax}MAX({maxColumn.column}){/if}{#if idMax}{maxColumn.column}{/if} FROM {table}
    {#each conditions}
{#if optional}{/if}
{#if compare}AND {table}.{column} {symbol:xml} {#if param}#{{input.{param}}}{/if}{#if literal}{#if quoted}{constant:sql-string-xml}{/if}{#if plain}{constant:xml}{/if}{/if}{/if}
{#if notNull}AND {table}.{column} IS NOT NULL{/if}
{#if inValues}AND {table}.{column} IN ({#each values}{#if quoted}{value:sql-string-xml}{/if}{#if plain}{value:xml}{/if}{#if more}, {/if}{/each}){/if}
{#if startsWith}AND LEFT({table}.{column}, CHAR_LENGTH({prefix:sql-string-xml})) = {prefix:sql-string-xml}{/if}
{#if collection}AND EXISTS (SELECT 1 FROM {link.table} l WHERE {#each link.keys}l.{column} = {table}.{parentColumn} AND {/each}l.{link.element.column} IN #{{item}})1 = 0{/if}
{#if optional}{/if}
{/each}
{#if idMax}    ORDER BY CHAR_LENGTH({maxColumn.column}) DESC, {maxColumn.column} DESC FETCH FIRST 1 ROW ONLY{/if}

{/if}
{#if insert}

    INSERT INTO {table} ({#each bindings}{column}{#if more}, {/if}{/each})
    VALUES ({#each bindings}{#if default}#{{input.{name}}}DEFAULT{/if}{#if noDefault}#{{input.{name}}}{/if}{#if more}, {/if}{/each})

{/if}
{#if update}

    UPDATE {table} SET
{#each writeGroups}    {column} = 
{#each branches}      {#if value.nil}NULL{/if}{#if value.param}#{{input.{value.param}}}{/if}{#if literal}{#if quoted}{value.constant:sql-string-xml}{/if}{#if plain}{value.constant:xml}{/if}{/if}
{/each}      {column}
    {#if more},{/if}
{/each}    {#each conditions}
{#if optional}{/if}
{#if compare}AND {table}.{column} {symbol:xml} {#if param}#{{input.{param}}}{/if}{#if literal}{#if quoted}{constant:sql-string-xml}{/if}{#if plain}{constant:xml}{/if}{/if}{/if}
{#if notNull}AND {table}.{column} IS NOT NULL{/if}
{#if inValues}AND {table}.{column} IN ({#each values}{#if quoted}{value:sql-string-xml}{/if}{#if plain}{value:xml}{/if}{#if more}, {/if}{/each}){/if}
{#if startsWith}AND LEFT({table}.{column}, CHAR_LENGTH({prefix:sql-string-xml})) = {prefix:sql-string-xml}{/if}
{#if collection}AND EXISTS (SELECT 1 FROM {link.table} l WHERE {#each link.keys}l.{column} = {table}.{parentColumn} AND {/each}l.{link.element.column} IN #{{item}})1 = 0{/if}
{#if optional}{/if}
{/each}

{/if}
{#if delete}
  DELETE FROM {table} {#each conditions}
{#if optional}{/if}
{#if compare}AND {table}.{column} {symbol:xml} {#if param}#{{input.{param}}}{/if}{#if literal}{#if quoted}{constant:sql-string-xml}{/if}{#if plain}{constant:xml}{/if}{/if}{/if}
{#if notNull}AND {table}.{column} IS NOT NULL{/if}
{#if inValues}AND {table}.{column} IN ({#each values}{#if quoted}{value:sql-string-xml}{/if}{#if plain}{value:xml}{/if}{#if more}, {/if}{/each}){/if}
{#if startsWith}AND LEFT({table}.{column}, CHAR_LENGTH({prefix:sql-string-xml})) = {prefix:sql-string-xml}{/if}
{#if collection}AND EXISTS (SELECT 1 FROM {link.table} l WHERE {#each link.keys}l.{column} = {table}.{parentColumn} AND {/each}l.{link.element.column} IN #{{item}})1 = 0{/if}
{#if optional}{/if}
{/each}
{/if}
{/each}
